-- Complete public Cat Parts Store "Bare Blocks" category snapshot.
-- Category page lists exactly nine records. No prices, stock, or guessed images are added.
-- Discontinued state is retained in provenance notes; these remain reference-only records.
on conflict (part_number) do update set
 name=excluded.name,description=excluded.description,engine_models=excluded.engine_models,
 technical_group=excluded.technical_group,source_name=excluded.source_name,source_url=excluded.source_url,
 source_note=excluded.source_note,verification_status='REFERENCE',
 image_url=coalesce(public.part_catalog.image_url,excluded.image_url),
 specifications=excluded.specifications,compatible_models=excluded.compatible_models,updated_at=now();
